import { ReactNode, FC } from 'react';

type NoticeBarMode = 'closeable' | 'link';
interface NoticeBarProps {
    /** 通知内容 */
    content: string;
    /** 模式 */
    mode?: NoticeBarMode;
    /** 左侧图标 */
    icon?: ReactNode;
    /** 是否滚动 */
    scrollable?: boolean;
    /** 滚动速度 (px/s) */
    speed?: number;
    /** 滚动延迟 (ms) */
    delay?: number;
    /** 背景色 */
    backgroundColor?: string;
    /** 文字颜色 */
    color?: string;
    /** 是否显示 (受控) */
    open?: boolean;
    /** 默认是否显示 (非受控) */
    defaultOpen?: boolean;
    /** 是否可见（兼容旧版，建议使用 open） */
    visible?: boolean;
    /** 关闭回调 */
    onClose?: () => void;
    /** 点击回调 */
    onClick?: () => void;
    /** 自定义类名 */
    className?: string;
}

declare const NoticeBar: FC<NoticeBarProps>;

export { NoticeBar, NoticeBar as default };
export type { NoticeBarMode, NoticeBarProps };
